pub struct OrderRepository {
    db_pool: sqlx::PgPool,
}

impl OrderRepository {
    pub async fn save(&self, order: &Order) -> Result<(), sqlx::Error> {
        // Leverages full power of sqlx and postgres directly
        sqlx::query!("INSERT INTO orders ...", order.id).execute(&self.db_pool).await?;
        Ok(())
    }
}
